export * from "./Context";
export * from "./EditorContent";
export * from "./Tiptap";
export * from "#/lib/tiptap/types";
export * from "#/lib/tiptap/useEditor";
export * from "./useEditorState";

import type { Editor } from "@tiptap/core";
import type { ComponentProps, JSX } from "solid-js";
import { createContext, splitProps, useContext } from "solid-js";

import { EditorContent } from "./EditorContent";
import type { UseEditorOptions } from "#/lib/tiptap/useEditor";
import { useEditor } from "#/lib/tiptap/useEditor";

export type EditorContextValue = {
  get editor(): Editor | null;
};

export const EditorContext = createContext<EditorContextValue>({
  get editor() {
    return null;
  },
});

/**
 * A hook to get the current editor instance.
 */
export const useCurrentEditor = () => useContext(EditorContext);

export interface EditorProviderProps extends UseEditorOptions {
  children?: JSX.Element;
  slotBefore?: JSX.Element;
  slotAfter?: JSX.Element;
  editorContainerProps?: ComponentProps<"div">;
}

/**
 * This is the provider component for the editor.
 * It allows the editor to be accessible across the entire component tree
 * with `useCurrentEditor`.
 */
export function EditorProvider(props: EditorProviderProps) {
  const [, editorOptions] = splitProps(props, [
    "children",
    "slotAfter",
    "slotBefore",
    "editorContainerProps",
  ]);
  // Spread so the accessor reads every option prop and `useEditor` re-syncs when one changes.
  const editor = useEditor(() => ({ ...editorOptions }));

  const contextValue = {
    get editor() {
      return editor();
    },
  };

  return (
    <EditorContext.Provider value={contextValue}>
      {props.slotBefore}
      <EditorContent editor={editor()} {...(props.editorContainerProps || {})} />
      {props.children}
      {props.slotAfter}
    </EditorContext.Provider>
  );
}

import type { Editor } from "@tiptap/core";
import type { ComponentProps } from "solid-js";
import { createEffect, createMemo, createSignal, For, onCleanup, splitProps } from "solid-js";
import { createStore } from "solid-js/store";
import { Dynamic, Portal } from "solid-js/web";
import type { ContentComponent, ContentRenderer, EditorWithContentComponent } from "#/lib/tiptap/editor";

export interface EditorContentProps extends ComponentProps<"div"> {
  editor: Editor | null;
}

function getInstance(): ContentComponent {
  const [renderers, setRenderers] = createStore<Record<string, ContentRenderer | undefined>>({});

  return {
    renderers,
    setRenderer(id: string, renderer: ContentRenderer) {
      setRenderers(id, renderer);
    },
    removeRenderer(id: string) {
      setRenderers(id, undefined);
    },
  };
}

export const EditorContent = (props: EditorContentProps) => {
  let editorContentRef: HTMLDivElement | undefined;
  const [local, rest] = splitProps(props, ["editor"]);
  const [content, setContent] = createSignal<ContentComponent | null>(null);

  createEffect(() => {
    const editor: EditorWithContentComponent | null = local.editor;
    const element = editorContentRef;

    if (!editor || editor.isDestroyed || !element) {
      return;
    }

    if (editor.contentComponent && editor.isEditorContentInitialized) {
      return;
    }

    if (editor.view.dom?.parentNode) {
      element.append(...Array.from(editor.view.dom.parentNode.childNodes));
    }

    editor.setOptions({
      element,
    });

    const instance = getInstance();
    editor.contentComponent = instance;
    setContent(instance);
    editor.createNodeViews();
    editor.isEditorContentInitialized = true;

    onCleanup(() => {
      editor.isEditorContentInitialized = false;
      setContent(null);

      if (!editor.isDestroyed) {
        editor.view.setProps({
          nodeViews: {},
        });
      }

      editor.contentComponent = null;

      try {
        if (!editor.view.dom?.parentNode) {
          return;
        }

        const newElement = document.createElement("div");
        newElement.append(...Array.from(editor.view.dom.parentNode.childNodes));

        editor.setOptions({
          element: newElement,
        });
      } catch {
        // do nothing
      }
    });
  });

  const renderers = createMemo((): ContentRenderer[] => {
    const store = content()?.renderers;
    if (!store) {
      return [];
    }

    return Object.values(store).filter((renderer): renderer is ContentRenderer => renderer != null);
  });

  // Node views render here, so they are owned by EditorContent: they see its context
  // and are disposed when their renderer is removed.
  return (
    <>
      <div ref={editorContentRef} {...rest} />
      <For each={renderers()}>
        {(renderer) => (
          <Portal mount={renderer.element}>
            <Dynamic component={renderer.component} {...renderer.props} />
          </Portal>
        )}
      </For>
    </>
  );
};

import type { Editor } from "@tiptap/core";
import type { JSX } from "solid-js";
import { type Accessor, createContext, useContext } from "solid-js";
import { EditorContext } from "./Context";
import { EditorContent, type EditorContentProps } from "./EditorContent";
import { type EditorStateSnapshot, useEditorState } from "./useEditorState";

/**
 * The shape of the Solid context used by the `<Tiptap />` components.
 */
export type TiptapContextType = {
  /** The Tiptap editor instance. */
  get editor(): Editor;
};

/**
 * Solid context that stores the current editor instance.
 */
export const TiptapContext = createContext<TiptapContextType>();

/**
 * Hook to read the Tiptap context and access the editor instance.
 */
export const useTiptap = () => {
  const ctx = useContext(TiptapContext);
  if (!ctx) {
    throw new Error("useTiptap must be used within a <Tiptap> provider");
  }
  return ctx;
};
export function useTiptapEditor<TEditor extends Editor | null = Editor | null>(
  e: Accessor<TEditor>,
): Accessor<TEditor>;
export function useTiptapEditor<TEditor extends Editor | null = Editor | null>(
  e?: Accessor<TEditor>,
): Accessor<TEditor | null>;
export function useTiptapEditor(e?: Accessor<Editor | null>): Accessor<Editor | null> {
  const tiptapCtx = useContext(TiptapContext);
  const legacyCtx = useContext(EditorContext);
  return () => {
    const fromAccessor = e?.();
    if (fromAccessor != null) {
      return fromAccessor;
    }
    if (tiptapCtx) {
      return tiptapCtx.editor;
    }
    return legacyCtx.editor;
  };
}

/**
 * Options for the `useTiptapState` hook.
 */
export type UseTiptapStateOptions<TSelectorResult, TEditor extends Editor | null> = {
  /**
   * The editor instance. If not provided, it will use the editor from the Tiptap context.
   */
  editor: Accessor<TEditor>;
  /**
   * A selector function to determine the value to compare for re-rendering.
   */
  selector: (context: EditorStateSnapshot<TEditor>) => TSelectorResult;
  /**
   * A custom equality function to determine if the component should re-render.
   */
  equalityFn?: (a: TSelectorResult, b: TSelectorResult | null) => boolean;
};
/**
 * Options for the `useTiptapState` hook.
 */
export type UseTiptapStateNullableOptions<TSelectorResult> = {
  /**
   * The editor instance. If not provided, it will use the editor from the Tiptap context.
   */
  editor?: never;
  /**
   * A selector function to determine the value to compare for re-rendering.
   */
  selector: (context: EditorStateSnapshot<Editor | null>) => TSelectorResult;
  /**
   * A custom equality function to determine if the component should re-render.
   */
  equalityFn?: (a: TSelectorResult, b: TSelectorResult | null) => boolean;
};

/**
 * Select a slice of the editor state using the context-provided editor.
 */
export function useTiptapState<TSelectorResult, TEditor extends Editor | null>(
  options: UseTiptapStateOptions<TSelectorResult, TEditor>,
): Accessor<TSelectorResult>;
export function useTiptapState<TSelectorResult>(
  options: UseTiptapStateNullableOptions<TSelectorResult>,
): Accessor<TSelectorResult>;
export function useTiptapState(
  options: UseTiptapStateNullableOptions<any> | UseTiptapStateOptions<any, any>,
) {
  const editor = useTiptapEditor(options.editor);

  return useEditorState({
    editor,
    selector: options.selector,
    equalityFn: options.equalityFn,
  });
}

/**
 * Props for the `Tiptap` root/provider component.
 */
export type TiptapWrapperProps = {
  editor: Accessor<Editor | null>;
  children: JSX.Element;
};

/**
 * Top-level provider component.
 */
export function Tiptap(props: TiptapWrapperProps) {
  const tiptapContextValue = {
    get editor() {
      const e = props.editor();
      if (!e) throw new Error("Tiptap: An editor instance is required.");
      return e;
    },
  };

  const legacyContextValue = {
    get editor() {
      return props.editor();
    },
  };

  return (
    <EditorContext.Provider value={legacyContextValue}>
      <TiptapContext.Provider value={tiptapContextValue}>{props.children}</TiptapContext.Provider>
    </EditorContext.Provider>
  );
}

/**
 * Convenience component that renders `EditorContent`.
 */
export function TiptapContent(props: Omit<EditorContentProps, "editor">) {
  const ctx = useTiptap();

  return <EditorContent editor={ctx.editor} {...props} />;
}

export default Tiptap;

import type { NodeViewProps as CoreNodeViewProps } from "@tiptap/core";

export type SolidNodeViewProps<T = HTMLElement> = CoreNodeViewProps & {
  ref: (element: T | null) => void;
};

import { Editor, type EditorOptions } from "@tiptap/core";
import {
  type Accessor,
  createEffect,
  createSignal,
  on,
  onCleanup,
  onMount,
  untrack,
} from "solid-js";

const isSSR = typeof window === "undefined";
const isDev =
  //@ts-expect-error
  typeof process !== "undefined" && process.env.NODE_ENV !== "production";
const isNext = isSSR || Boolean(typeof window !== "undefined" && (window as any).next);

export type UseEditorOptions = Partial<EditorOptions> & {
  /**
   * Whether to render the editor on the first render.
   * If client-side rendering, set this to `true`.
   * If server-side rendering, set this to `false`.
   * @default true
   */
  immediatelyRender?: boolean;
  /**
   * Accepted for parity with Tiptap React and ignored: Solid has no component re-render.
   * Read editor state with `useEditorState` instead.
   * @default false
   */
  shouldRerenderOnTransaction?: boolean;
};

function compareOptions(a: UseEditorOptions, b: UseEditorOptions) {
  const keys = Object.keys(a) as (keyof UseEditorOptions)[];
  return keys.every((key) => {
    if (
      [
        "onCreate",
        "onBeforeCreate",
        "onDestroy",
        "onUpdate",
        "onTransaction",
        "onFocus",
        "onBlur",
        "onSelectionUpdate",
        "onContentError",
        "onDrop",
        "onPaste",
      ].includes(key)
    ) {
      // we don't want to compare callbacks, they are always different and only registered once
      return true;
    }

    // We often encourage putting extensions inlined in the options object, so we will do a slightly deeper comparison here
    if (key === "extensions" && a.extensions && b.extensions) {
      if (a.extensions.length !== b.extensions.length) {
        return false;
      }
      return a.extensions.every((extension, index) => {
        return extension === b.extensions?.[index];
      });
    }

    if (a[key] !== b[key]) {
      // if any of the options have changed, we should update the editor options
      return false;
    }
    return true;
  });
}

function shouldRecreate(a: UseEditorOptions, b: UseEditorOptions) {
  if (a.extensions !== b.extensions) {
    if (!a.extensions || !b.extensions) {
      return true;
    }
    if (a.extensions.length !== b.extensions.length) {
      return true;
    }
    if (a.extensions.some((extension, index) => extension !== b.extensions?.[index])) {
      return true;
    }
  }
  return false;
}

export function useEditor(
  options: Accessor<UseEditorOptions & { immediatelyRender: false }>,
): Accessor<Editor | null>;
export function useEditor(options: Accessor<UseEditorOptions>): Accessor<Editor>;
export function useEditor(
  options: Accessor<UseEditorOptions> = () => ({}),
): Accessor<Editor | null> {
  const [editor, setEditor] = createSignal<Editor | null>(null);
  let instanceId = "";
  let isComponentMounted = false;
  let scheduledDestructionTimeout: ReturnType<typeof setTimeout> | undefined;

  const createEditorInstance = (opts: UseEditorOptions): Editor => {
    const instance = new Editor({
      ...opts,
      // Always call the most recent version of the callback function by default
      onBeforeCreate: (...args) => options().onBeforeCreate?.(...args),
      onBlur: (...args) => options().onBlur?.(...args),
      onCreate: (...args) => options().onCreate?.(...args),
      onDestroy: (...args) => options().onDestroy?.(...args),
      onFocus: (...args) => options().onFocus?.(...args),
      onSelectionUpdate: (...args) => options().onSelectionUpdate?.(...args),
      onTransaction: (...args) => options().onTransaction?.(...args),
      onUpdate: (...args) => options().onUpdate?.(...args),
      onContentError: (...args) => options().onContentError?.(...args),
      onDrop: (...args) => options().onDrop?.(...args),
      onPaste: (...args) => options().onPaste?.(...args),
      onDelete: (...args) => options().onDelete?.(...args),
    });

    instanceId = Math.random().toString(36).slice(2, 9);
    return instance;
  };

  const refreshEditorInstance = (opts: UseEditorOptions) => {
    const currentInstance = untrack(editor);
    if (currentInstance && !currentInstance.isDestroyed) {
      currentInstance.destroy();
    }

    setEditor(createEditorInstance(opts));
  };

  const scheduleDestroy = (instance: Editor | null, id: string) => {
    if (!instance) {
      return;
    }

    scheduledDestructionTimeout = setTimeout(() => {
      if (isComponentMounted && instanceId === id) {
        // If still mounted on the following tick, with the same instanceId, do not destroy the editor
        // just re-apply options as they might have changed
        instance.setOptions(untrack(options));
        return;
      }

      if (!instance.isDestroyed) {
        instance.destroy();
        if (instanceId === id) {
          setEditor(null);
        }
      }
    }, 1);
  };

  // Initial creation logic
  const getInitialEditor = () => {
    const opts = untrack(options);
    if (opts.immediatelyRender === undefined) {
      if (isSSR || isNext) {
        if (isDev) {
          throw new Error(
            "Tiptap Error: SSR has been detected, please set `immediatelyRender` explicitly to `false` to avoid hydration mismatches.",
          );
        }
        return null;
      }
      return createEditorInstance(opts);
    }

    if (opts.immediatelyRender && isSSR && isDev) {
      throw new Error(
        "Tiptap Error: SSR has been detected, and `immediatelyRender` has been set to `true` this is an unsupported configuration that may result in errors, explicitly set `immediatelyRender` to `false` to avoid hydration mismatches.",
      );
    }

    if (opts.immediatelyRender) {
      return createEditorInstance(opts);
    }

    return null;
  };

  const initial = getInitialEditor();
  if (initial) {
    setEditor(initial);
  }

  onMount(() => {
    isComponentMounted = true;
    clearTimeout(scheduledDestructionTimeout);

    const instance = untrack(editor);
    if (!instance && !isSSR) {
      refreshEditorInstance(untrack(options));
    }
  });

  onCleanup(() => {
    isComponentMounted = false;
    scheduleDestroy(untrack(editor), instanceId);
  });

  // Re-sync options or recreate
  createEffect(
    on(
      options,
      (opts) => {
        const instance = untrack(editor);
        if (!instance || instance.isDestroyed) {
          if (isComponentMounted) {
            refreshEditorInstance(opts);
          }
          return;
        }

        if (shouldRecreate(opts, instance.options)) {
          refreshEditorInstance(opts);
        } else if (!compareOptions(opts, instance.options)) {
          instance.setOptions({
            ...opts,
            editable: opts.editable ?? instance.isEditable,
          });
        }
      },
      { defer: true },
    ),
  );

  return editor;
}

import type { Editor } from "@tiptap/core";
import { deepEqual } from "fast-equals";
import { type Accessor, createEffect, createMemo, createSignal, onCleanup } from "solid-js";
import { useTiptapEditor } from "./Tiptap";

export type EditorStateSnapshot<TEditor extends Editor | null = Editor | null> = {
  editor: TEditor;
  transactionNumber: number;
};

export type UseEditorStateOptions<
  TSelectorResult,
  TEditor extends Editor | null = Editor | null,
> = {
  /**
   * The editor instance.
   */
  editor?: Accessor<TEditor>;
  /**
   * A selector function to determine the value to compare for re-rendering.
   */
  selector: (context: EditorStateSnapshot<TEditor>) => TSelectorResult;
  /**
   * A custom equality function to determine if the editor should re-render.
   * @default `deepEqual` from `fast-equals`
   */
  equalityFn?: (a: TSelectorResult, b: TSelectorResult | null) => boolean;
};

export function useEditorState<TSelectorResult>(
  options: UseEditorStateOptions<TSelectorResult, Editor | null>,
): Accessor<TSelectorResult> {
  const [transactionNumber, setTransactionNumber] = createSignal(0);
  const getEditor = useTiptapEditor(options.editor);

  createEffect(() => {
    const editor = getEditor();

    if (!editor) {
      return;
    }

    const handler = () => {
      setTransactionNumber((n) => n + 1);
    };

    editor.on("transaction", handler);

    onCleanup(() => {
      editor.off("transaction", handler);
    });
  });

  const selectedState = createMemo((prev: TSelectorResult | null) => {
    const editor = getEditor();
    const next = options.selector({
      editor,
      transactionNumber: transactionNumber(),
    });
    const equalityFn = options.equalityFn ?? deepEqual;

    if (prev != null && equalityFn(next, prev)) {
      return prev;
    }

    return next;
  }, null);

  return selectedState;
}

import type { Editor } from "@tiptap/core";
import type { Component } from "solid-js";
import type { Store } from "solid-js/store";

export type AnyProps = Record<string, any>;

export type ContentRenderer<P extends AnyProps = AnyProps> = {
  id: string;
  element: HTMLElement;
  component: Component<P>;
  props: P;
};

export type EditorWithContentComponent<P extends AnyProps = AnyProps> = Editor & {
  contentComponent?: ContentComponent<P> | null;
  isEditorContentInitialized?: boolean;
};

export type ContentComponent<P extends AnyProps = AnyProps> = {
  setRenderer(id: string, renderer: ContentRenderer<P>): void;
  removeRenderer(id: string): void;
  renderers: Readonly<Store<Record<string, ContentRenderer<P> | undefined>>>;
};
